input.command:
cd /workspace/pr/head; for f in $(git -C /workspace/pr diff --no-index --name-only /dev/null /dev/null 2>/dev/null; grep -l . $(grep '^diff --git' ../head.diff | awk '{print substr($4,3)}' | grep '\.bats$')); do awk -v F="$f" '
/^@test/ {intest=1; n=0; delete L; next}
intest && /^}/ { for (i=1;i<n;i++) if (L[i] ~ /^[[:space:]]*! /) print F":"N[i]": "L[i]; intest=0; next}
intest { if ($0 ~ /[^[:space:]]/) { n++; L[n]=$0; N[n]=NR } }
' "$f"; done
